def estimate_mathjax_preview_height(text, min_height=220, max_height=900):
    text = str(text or "")
    line_count = max(1, len(text.splitlines()))
    table_bonus = 120 if "|" in text else 0
    formula_bonus = 120 if any(token in text for token in ["$$", "\\(", "\\[", "\\frac", "\\sum", "\\bar"]) else 0
    estimated = 120 + line_count * 20 + table_bonus + formula_bonus
    return max(min_height, min(max_height, estimated))


def render_markdown_with_mathjax(markdown_text, key_suffix="default", height=None):
    markdown_text = str(markdown_text or "").strip()
    if not markdown_text:
        return

    if height is None:
        height = estimate_mathjax_preview_height(markdown_text)

    rendered_html = _markdown_with_tables(markdown_text)

    preview_html = f"""
    <!DOCTYPE html>
    <html>
    <head>
        <meta charset="utf-8" />
        <script>
            window.MathJax = {{
                tex: {{
                    inlineMath: [['$', '$'], ['\\\\(', '\\\\)']],
                    displayMath: [['$$', '$$'], ['\\\\[', '\\\\]']]
                }},
                options: {{
                    skipHtmlTags: ['script', 'noscript', 'style', 'textarea', 'pre', 'code']
                }}
            }};
        </script>
        <script async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"></script>
        <style>
            body {{
                margin: 0;
                padding: 0;
                background: white;
                color: #111827;
                font-family: Arial, sans-serif;
            }}
            .preview-shell {{
                padding: 16px;
                border: 1px solid #e5e7eb;
                border-radius: 10px;
                box-sizing: border-box;
            }}
            .preview-shell h1, .preview-shell h2, .preview-shell h3, .preview-shell h4 {{
                margin-top: 0.8rem;
                margin-bottom: 0.4rem;
            }}
            .preview-shell p, .preview-shell li {{
                line-height: 1.5;
            }}
            .preview-shell table {{
                border-collapse: collapse;
                width: 100%;
                margin: 0.8rem 0;
            }}
            .preview-shell th, .preview-shell td {{
                border: 1px solid #d1d5db;
                padding: 6px 8px;
                text-align: left;
            }}
            .preview-shell code {{
                background: #f3f4f6;
                padding: 2px 4px;
                border-radius: 4px;
            }}
            .preview-shell pre {{
                background: #f9fafb;
                padding: 12px;
                border-radius: 8px;
                overflow-x: auto;
            }}
        </style>
    </head>
    <body>
        <div class="preview-shell">
            {rendered_html}
        </div>
    </body>
    </html>
    """
    html(preview_html, height=height, scrolling=True)


def render_mermaid_diagram(mermaid_code, key_suffix="default", height=420):
    mermaid_code = str(mermaid_code).strip()
    if not mermaid_code:
        return

    mermaid_html = f"""
    <!DOCTYPE html>
    <html>
    <head>
        <script src="https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.min.js"></script>
        <style>
            html, body {{
                margin: 0;
                padding: 0;
                width: 100%;
                height: 100%;
                background: white;
                overflow: hidden;
                font-family: Arial, sans-serif;
            }}
            .diagram-shell {{
                width: 100%;
                height: 100%;
                min-height: {height - 20}px;
                overflow: auto;
                border: 1px solid #e0e0e0;
                border-radius: 8px;
                background: #fafafa;
                padding: 16px;
                box-sizing: border-box;
            }}
            .mermaid {{
                min-width: max-content;
            }}
        </style>
    </head>
    <body>
        <div class="diagram-shell">
            <div class="mermaid">
{mermaid_code}
            </div>
        </div>
        <script>
            mermaid.initialize({{
                startOnLoad: true,
                securityLevel: 'loose',
                theme: 'default',
                flowchart: {{ useMaxWidth: false, htmlLabels: true }}
            }});
        </script>
    </body>
    </html>
    """
    html(mermaid_html, height=height, scrolling=False)


