def looks_like_technical_token(display, token_key):
    display = str(display or "")
    token_key = str(token_key or "")
    if not display or not token_key:
        return False
    is_acronym = display.isupper() and len(display) >= 2
    has_technical_suffix = any(token_key.endswith(suffix) for suffix in GLOSSARY_TECHNICAL_SUFFIXES)
    has_mixed_form = ("_" in display or "-" in display or any(ch.isdigit() for ch in display))
    is_domain_head = token_key in GLOSSARY_DOMAIN_HEADWORDS
    return is_acronym or has_technical_suffix or has_mixed_form or is_domain_head


def describe_candidate_reason(display, token_key, is_phrase=False):
    display = str(display or "")
    token_key = str(token_key or "")
    if token_key in GLOSSARY_DOMAIN_PHRASES:
        return "Strong subject phrase used in this lesson"
    if display.isupper() and len(display) >= 2:
        return "Technical acronym or formula-style term"
    if "_" in display or "-" in display:
        return "Structured technical term used in context"
    if token_key in GLOSSARY_DOMAIN_HEADWORDS:
        return "Core subject term for this lesson"
    if any(token_key.endswith(suffix) for suffix in GLOSSARY_TECHNICAL_SUFFIXES):
        return "Academic or technical wording worth defining"
    if is_phrase:
        return "Likely subject phrase from the lesson context"
    return "Potentially difficult term from the lesson"


def extract_term_context_snippet(text, term, max_chars=220):
    plain_text = re.sub(r"<[^>]+>", " ", str(text or ""))
    plain_text = re.sub(r"\s+", " ", plain_text).strip()
    if not plain_text:
        return ""
    match = re.search(re.escape(str(term or "")), plain_text, flags=re.IGNORECASE)
    if not match:
        return plain_text[:max_chars].strip()

    start = max(0, match.start() - max_chars // 2)
    end = min(len(plain_text), match.end() + max_chars // 2)
    snippet = plain_text[start:end].strip()
    if start > 0:
        snippet = "..." + snippet
    if end < len(plain_text):
        snippet = snippet + "..."
    return snippet


def fallback_glossary_suggestion(term, lesson_text, lesson_title=""):
    snippet = extract_term_context_snippet(lesson_text, term)
    title_bit = f" in '{lesson_title}'" if lesson_title else ""
    return {
        "plain": f"{term} is a key term that appears{title_bit}.",
        "context": snippet or f"{term} appears in this lesson and is worth defining before moving on.",
        "read_more": "Save your own example, formula, or plain-language reminder here so the meaning is easier to remember next time.",
    }


def generate_glossary_suggestion(term, lesson_text, lesson_title="", course_name=""):
    cache = st.session_state.setdefault("glossary_suggestion_cache", {})
    cache_key = f"{course_name}::{lesson_title}::{str(term or '').strip().lower()}"
    if cache_key in cache:
        return cache[cache_key]

    fallback = fallback_glossary_suggestion(term, lesson_text, lesson_title=lesson_title)

    if client is None:
        cache[cache_key] = fallback
        return fallback

    snippet = extract_term_context_snippet(lesson_text, term, max_chars=500)
    if ai_provider_is_local():
        mode_config = get_local_ai_mode_config()
        prompt = (
            "Build a tiny study glossary entry. "
            "Return JSON only with keys plain, context, read_more. "
            "Use simple English. "
            f"plain: max {mode_config['glossary_plain_words']} words. "
            f"context: max {mode_config['glossary_context_words']} words. "
            f"read_more: max {mode_config['glossary_read_more_words']} words. "
            "Do not add extra keys.\n\n"
            f"Course: {course_name}\n"
            f"Lesson: {lesson_title}\n"
            f"Term: {term}\n"
            f"Lesson excerpt: {snippet}"
        )
        max_tokens = mode_config["glossary_tokens"]
    else:
        prompt = (
            "You are helping build a study glossary. "
            "Return strict JSON with keys plain, context, read_more. "
            "Keep plain under 18 words, context under 35 words, and read_more under 60 words. "
            "Use simple student-friendly English.\n\n"
            f"Course: {course_name}\n"
            f"Lesson: {lesson_title}\n"
            f"Term: {term}\n"
            f"Lesson excerpt: {snippet}"
        )
        max_tokens = 180

    try:
        response = client.chat.completions.create(
            model=AI_CHAT_MODEL,
            messages=[
                {"role": "system", "content": "Return only valid JSON."},
                {"role": "user", "content": prompt},
            ],
            max_tokens=max_tokens,
        )
        raw_text = response.choices[0].message.content.strip()
        json_match = re.search(r"\{.*\}", raw_text, flags=re.DOTALL)
        payload = json.loads(json_match.group(0) if json_match else raw_text)
        suggestion = {
            "plain": str(payload.get("plain") or fallback["plain"]).strip(),
            "context": str(payload.get("context") or fallback["context"]).strip(),
            "read_more": str(payload.get("read_more") or fallback["read_more"]).strip(),
        }
    except Exception:
        suggestion = fallback

    cache[cache_key] = suggestion
    return suggestion


def fallback_selection_explanation(selected_text, lesson_text, lesson_title="", course_name=""):
    snippet = extract_term_context_snippet(lesson_text, selected_text, max_chars=280)
    scope = "this lesson"
    if lesson_title:
        scope = f"Lesson {lesson_title}"
    if course_name:
        scope = f"{course_name}, {scope}"
    return (
        f"**What this means:** The selected text is being discussed in {scope}. "
        f"It is worth slowing down and identifying what the question or concept is really asking.\n\n"
        f"**Why it matters:** {snippet or 'This part should be read together with the surrounding lesson content to understand the main idea and what you are expected to explain.'}\n\n"
        f"**Exam-safe version:** Break it into three parts: what the key concept is, what relationship or rule is being described, and how you would explain it in plain exam language."
    )


def generate_selection_explanation(selected_text, lesson_text, lesson_title="", course_name=""):
    cache = st.session_state.setdefault("selection_explanation_cache", {})
    cache_key = f"{course_name}::{lesson_title}::{str(selected_text or '').strip().lower()}"
    if cache_key in cache:
        return cache[cache_key]

    fallback = fallback_selection_explanation(selected_text, lesson_text, lesson_title=lesson_title, course_name=course_name)
    if client is None:
        cache[cache_key] = fallback
        return fallback

    snippet = extract_term_context_snippet(lesson_text, selected_text, max_chars=700)
    if ai_provider_is_local():
        mode_config = get_local_ai_mode_config()
        prompt = (
            "Explain the selected text for a student. "
            "Return markdown only. "
            "Use exactly these bold headings: **What this means**, **Why it matters**, **Exam-safe version**. "
            "Write 1 short paragraph under each heading. "
            f"Keep each part under {mode_config['selection_words']} words. "
            "Use plain English. "
            "No bullets. No intro. No extra headings.\n\n"
            f"Course: {course_name}\n"
            f"Lesson: {lesson_title}\n"
            f"Selected text: {selected_text}\n"
            f"Lesson excerpt: {snippet}"
        )
        max_tokens = mode_config["selection_tokens"]
    else:
        prompt = (
            "You are helping a student understand a selected sentence, question, or concept from lesson notes. "
            "Write a short, human explanation in markdown. "
            "Use three short parts with bold headings: 'What this means', 'Why it matters', and 'Exam-safe version'. "
            "Keep it concise, practical, and student-friendly. "
            "Do not mention that you are an AI.\n\n"
            f"Course: {course_name}\n"
            f"Lesson: {lesson_title}\n"
            f"Selected text: {selected_text}\n"
            f"Lesson excerpt: {snippet}"
        )
        max_tokens = 320

    try:
        response = client.chat.completions.create(
            model=AI_CHAT_MODEL,
            messages=[
                {"role": "system", "content": "Return helpful markdown only."},
                {"role": "user", "content": prompt},
            ],
            max_tokens=max_tokens,
        )
        explanation = response.choices[0].message.content.strip()
    except Exception:
        explanation = fallback

    cache[cache_key] = explanation
    return explanation


def fallback_selection_exam_answer(selected_text, lesson_text, lesson_title="", course_name=""):
    snippet = extract_term_context_snippet(lesson_text, selected_text, max_chars=320)
    scope = "this lesson"
    if lesson_title:
        scope = f"Lesson {lesson_title}"
    if course_name:
        scope = f"{course_name}, {scope}"
    return (
        f"**Direct answer:** The selected text should be answered by stating the main concept clearly and then linking it to the lesson context.\n\n"
        f"**Why this answer fits:** The question comes from {scope}, so the safest exam approach is to define the concept, explain the relationship or rule, and keep the wording direct.\n\n"
        f"**Exam-safe version:** {snippet or 'Write a short answer that defines the key idea, explains why it matters, and connects it to the course language used in the lesson.'}"
    )


def generate_selection_exam_answer(selected_text, lesson_text, lesson_title="", course_name=""):
    cache = st.session_state.setdefault("selection_exam_answer_cache", {})
    cache_key = f"{course_name}::{lesson_title}::{str(selected_text or '').strip().lower()}"
    if cache_key in cache:
        return cache[cache_key]

    fallback = fallback_selection_exam_answer(selected_text, lesson_text, lesson_title=lesson_title, course_name=course_name)
    if client is None:
        cache[cache_key] = fallback
        return fallback

    snippet = extract_term_context_snippet(lesson_text, selected_text, max_chars=700)
    if ai_provider_is_local():
        mode_config = get_local_ai_mode_config()
        prompt = (
            "Write a short exam answer for the selected text. "
            "Return markdown only. "
            "Use exactly these bold headings: **Direct answer**, **Why this answer fits**, **Exam-safe version**. "
            "Write 1 short paragraph under each heading. "
            f"Keep each part under {mode_config['answer_words']} words. "
            "Use clear exam English. "
            "No bullets. No intro. No extra headings.\n\n"
            f"Course: {course_name}\n"
            f"Lesson: {lesson_title}\n"
            f"Selected text: {selected_text}\n"
            f"Lesson excerpt: {snippet}"
        )
        max_tokens = mode_config["answer_tokens"]
    else:
        prompt = (
            "You are helping a student answer a selected question or sentence from course notes. "
            "Write a short exam-style answer in markdown. "
            "Use three short parts with bold headings: 'Direct answer', 'Why this answer fits', and 'Exam-safe version'. "
            "Keep the tone human, concise, and easy to reuse in an exam. "
            "Do not mention that you are an AI.\n\n"
            f"Course: {course_name}\n"
            f"Lesson: {lesson_title}\n"
            f"Selected text: {selected_text}\n"
            f"Lesson excerpt: {snippet}"
        )
        max_tokens = 360

    try:
        response = client.chat.completions.create(
            model=AI_CHAT_MODEL,
            messages=[
                {"role": "system", "content": "Return helpful markdown only."},
                {"role": "user", "content": prompt},
            ],
            max_tokens=max_tokens,
        )
        answer = response.choices[0].message.content.strip()
    except Exception:
        answer = fallback

    cache[cache_key] = answer
    return answer


def trigger_clipboard_copy(text, key_suffix="default"):
    payload = json.dumps(str(text or ""))
    html(
        f"""
        <script>
          const textToCopy = {payload};
          const fallbackCopy = () => {{
            const area = document.createElement("textarea");
            area.value = textToCopy;
            area.setAttribute("readonly", "");
            area.style.position = "fixed";
            area.style.opacity = "0";
            document.body.appendChild(area);
            area.focus();
            area.select();
            try {{
              document.execCommand("copy");
            }} catch (err) {{}}
            document.body.removeChild(area);
          }};

          if (navigator.clipboard && navigator.clipboard.writeText) {{
            navigator.clipboard.writeText(textToCopy).catch(() => fallbackCopy());
          }} else {{
            fallbackCopy();
          }}
        </script>
        """,
        height=0,
        key=f"clipboard_copy_{key_suffix}",
    )


def save_ai_text_to_study_notes(course_code, title, markdown_content, tags=None, category="exam", importance="important", learning_outcome=""):
    if "study_notes" not in st.session_state:
        st.session_state.study_notes = {}
    if course_code not in st.session_state.study_notes:
        st.session_state.study_notes[course_code] = []

    rendered_html = _markdown_with_tables(str(markdown_content or "").strip())
    note_data = {
        "title": str(title or "AI Note").strip(),
        "content": rendered_html,
        "date": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "tags": list(tags or []),
        "category": category,
        "importance": importance,
        "learning_outcome": learning_outcome,
        "version_history": [],
    }
    st.session_state.study_notes[course_code].append(note_data)
    return True, f"Saved to Study Notes for {course_code}."


def detect_difficult_word_candidates(text, glossary_entries, max_candidates=10):
    plain_text = re.sub(r"<[^>]+>", " ", str(text or ""))
    plain_text = re.sub(r"[*_`>#\[\]\(\)\|]", " ", plain_text)
    plain_text = re.sub(r"\s+", " ", plain_text).strip()
    if not plain_text:
        return []

    known_terms = set()
    for canonical_term, meta in (glossary_entries or {}).items():
        known_terms.add(canonical_term.lower())
        for alias in meta.get("_aliases", []):
            known_terms.add(str(alias).lower())

    phrase_candidates = {}
    phrase_pattern = re.compile(r"\b([A-Za-z][A-Za-z0-9_-]{1,}(?:\s+[A-Za-z][A-Za-z0-9_-]{1,}){1,2})\b")
    for phrase_match in phrase_pattern.finditer(plain_text):
        display = phrase_match.group(1).strip()
        phrase_key = display.lower()
        phrase_words = [word.strip().lower() for word in display.split()]
        if phrase_key in known_terms:
            continue
        if not phrase_words or all(word in GLOSSARY_STOPWORDS for word in phrase_words):
            continue
        if phrase_words[0] in GLOSSARY_STOPWORDS:
            continue
        phrase_is_domain = (
            phrase_key in GLOSSARY_DOMAIN_PHRASES
            or any(word in GLOSSARY_DOMAIN_HEADWORDS for word in phrase_words)
            or any(looks_like_technical_token(word, word.lower()) for word in display.split())
        )
        if not phrase_is_domain:
            continue
        entry = phrase_candidates.setdefault(
            phrase_key,
            {"term": display, "count": 0, "score": 0, "reason": describe_candidate_reason(display, phrase_key, is_phrase=True)},
        )
        entry["count"] += 1
        entry["score"] += 28 + (6 * entry["count"]) + len(display)

    raw_tokens = re.findall(r"[A-Za-z][A-Za-z0-9_-]{1,}", plain_text)
    token_counts = Counter()
    token_display = {}
    for token in raw_tokens:
        token_key = token.lower()
        token_counts[token_key] += 1
        token_display.setdefault(token_key, token)

    ranked = []
    for token_key, count in token_counts.items():
        display = token_display[token_key]
        if token_key in known_terms or token_key in GLOSSARY_STOPWORDS:
            continue
        if display.isdigit():
            continue
        is_technical = looks_like_technical_token(display, token_key)
        if len(display) < 6 and count < 2 and not is_technical:
            continue
        if not is_technical and count < 2:
            continue
        score = count * 8 + len(display)
        if display.isupper() and len(display) >= 2:
            score += 26
        if token_key in GLOSSARY_DOMAIN_HEADWORDS:
            score += 20
        if any(token_key.endswith(suffix) for suffix in GLOSSARY_TECHNICAL_SUFFIXES):
            score += 14
        if "_" in display or "-" in display or any(ch.isdigit() for ch in display):
            score += 12
        ranked.append(
            {
                "score": score,
                "term": display,
                "count": count,
                "reason": describe_candidate_reason(display, token_key),
            }
        )

    merged_ranked = {}
    for candidate in ranked:
        merged_ranked[candidate["term"].lower()] = candidate
    for phrase_key, candidate in phrase_candidates.items():
        existing = merged_ranked.get(phrase_key)
        if existing is None or candidate["score"] > existing["score"]:
            merged_ranked[phrase_key] = candidate

    final_ranked = sorted(
        merged_ranked.values(),
        key=lambda item: (-item["score"], -item["count"], item["term"].lower()),
    )

    return [
        {
            "term": candidate["term"],
            "count": candidate["count"],
            "reason": candidate["reason"],
            "snippet": extract_term_context_snippet(plain_text, candidate["term"], max_chars=180),
        }
        for candidate in final_ranked[:max_candidates]
    ]


def protect_code_segments(text):
    replacements = {}

    def _store(match):
        placeholder = f"@@GLOSSARY_CODE_{len(replacements)}@@"
        replacements[placeholder] = match.group(0)
        return placeholder

    protected = re.sub(r"```.*?```|`[^`\n]+`", _store, str(text or ""), flags=re.DOTALL)
    return protected, replacements


def restore_code_segments(text, replacements):
    restored = str(text or "")
    for placeholder, original in replacements.items():
        restored = restored.replace(placeholder, original)
    return restored


def make_glossary_span(display_text, canonical_term, meta):
    plain = meta.get("plain") or canonical_term
    context = meta.get("context") or plain
    read_more = meta.get("read_more") or ""
    scope_label = meta.get("_scope_label") or ""
    tooltip = meta.get("tooltip") or context or plain or canonical_term
    return (
        f'<span class="glossary-term" tabindex="0" '
        f'data-glossary-term="{html_escape(canonical_term)}" '
        f'title="{html_escape(tooltip)}">'
        f'<span class="glossary-term-label">{html_escape(display_text)}</span>'
        f'<span class="glossary-hover-card" role="note" aria-label="{html_escape(canonical_term)} definition">'
        f'<span class="glossary-hover-term">{html_escape(canonical_term)}</span>'
        f'<span class="glossary-hover-plain">{html_escape(plain)}</span>'
        f'<span class="glossary-hover-context">{html_escape(context)}</span>'
        f'{f"<span class=\"glossary-hover-readmore\">{html_escape(read_more)}</span>" if read_more else ""}'
        f'{f"<span class=\"glossary-hover-scope\">{html_escape(scope_label)}</span>" if scope_label else ""}'
        f'</span></span>'
    )


def strip_basic_markdown(text):
    value = str(text or "").strip()
    if not value:
        return ""
    value = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", value)
    value = re.sub(r"`([^`]+)`", r"\1", value)
    value = re.sub(r"\*\*([^*]+)\*\*", r"\1", value)
    value = re.sub(r"\*([^*]+)\*", r"\1", value)
    value = re.sub(r"^#+\s*", "", value, flags=re.MULTILINE)
    value = re.sub(r"\n{2,}", "\n", value)
    value = re.sub(r"\s+", " ", value)
    return value.strip()


def extract_markdown_section(markdown_text, heading, fallback=""):
    text = str(markdown_text or "")
    if not text:
        return fallback
    pattern = re.compile(
        rf"\*\*{re.escape(heading)}:\*\*\s*(.*?)(?=\n\s*\*\*[A-Z][^*]+:\*\*|\Z)",
        flags=re.IGNORECASE | re.DOTALL,
    )
    match = pattern.search(text)
    if not match:
        return fallback
    return strip_basic_markdown(match.group(1))


def build_selection_hover_meta(selected_text, explanation_output="", explain_mode="explain"):
    selected_text = str(selected_text or "").strip()
    explanation_output = str(explanation_output or "").strip()
    explain_mode = str(explain_mode or "explain").strip().lower()

    if explain_mode == "answer":
        plain = extract_markdown_section(explanation_output, "Direct answer", fallback="Short exam-style answer for the selected text.")
        context = extract_markdown_section(explanation_output, "Why this answer fits", fallback=plain)
        read_more = extract_markdown_section(explanation_output, "Exam-safe version", fallback="")
        scope_label = "AI exam answer"
        tooltip = plain or "AI exam-style answer for the selected text."
    else:
        plain = extract_markdown_section(explanation_output, "What this means", fallback="AI explanation for the selected text.")
        context = extract_markdown_section(explanation_output, "Why it matters", fallback=plain)
        read_more = extract_markdown_section(explanation_output, "Exam-safe version", fallback="")
        scope_label = "AI explanation"
        tooltip = plain or "AI explanation for the selected text."

    if not explanation_output:
        context = context or f"The selected text is currently being explained in this lesson."
        read_more = read_more or ""

    return {
        "plain": plain or selected_text,
        "context": context or plain or selected_text,
        "read_more": read_more,
        "scope_label": scope_label,
        "tooltip": tooltip or selected_text,
    }


def make_selection_highlight_span(display_text, selected_text, explanation_output="", explain_mode="explain"):
    meta = build_selection_hover_meta(selected_text, explanation_output=explanation_output, explain_mode=explain_mode)
    plain = meta["plain"]
    context = meta["context"]
    read_more = meta["read_more"]
    scope_label = meta["scope_label"]
    tooltip = meta["tooltip"]
    return (
        f'<span class="glossary-term selection-explain-highlight" tabindex="0" '
        f'data-selection-highlight="true" '
        f'data-selection-mode="{html_escape(explain_mode)}" '
        f'title="{html_escape(tooltip)}">'
        f'<span class="glossary-term-label">{html_escape(display_text)}</span>'
        f'<span class="glossary-hover-card" role="note" aria-label="{html_escape(selected_text)} AI explanation">'
        f'<span class="glossary-hover-term">{html_escape(selected_text)}</span>'
        f'<span class="glossary-hover-plain">{html_escape(plain)}</span>'
        f'<span class="glossary-hover-context">{html_escape(context)}</span>'
        f'{f"<span class=\"glossary-hover-readmore\">{html_escape(read_more)}</span>" if read_more else ""}'
        f'<span class="glossary-hover-scope">{html_escape(scope_label)}</span>'
        f'</span></span>'
    )


def annotate_text_with_selection_highlight(text, selected_text, explanation_output="", explain_mode="explain", max_occurrences=1):
    selected_text = str(selected_text or "").strip()
    if not text or not selected_text:
        return text, {}

    protected_text, code_replacements = protect_code_segments(text)
    html_parts = re.split(r"(<[^>]+>)", protected_text)
    annotated_parts = []
    selection_replacements = {}
    replacements_made = 0

    escaped_selection = re.escape(selected_text)
    flexible_pattern = escaped_selection.replace(r"\ ", r"\s+")
    selection_pattern = re.compile(flexible_pattern, flags=re.IGNORECASE)

    for html_part in html_parts:
        if html_part.startswith("<") and html_part.endswith(">"):
            annotated_parts.append(html_part)
            continue

        if replacements_made >= max_occurrences:
            annotated_parts.append(html_part)
            continue

        def _replace(match):
            nonlocal replacements_made
            if replacements_made >= max_occurrences:
                return match.group(0)
            placeholder = f"@@SELECTION_HIGHLIGHT_{len(selection_replacements)}@@"
            selection_replacements[placeholder] = make_selection_highlight_span(
                match.group(0),
                selected_text,
                explanation_output=explanation_output,
                explain_mode=explain_mode,
            )
            replacements_made += 1
            return placeholder

        annotated_parts.append(selection_pattern.sub(_replace, html_part, count=max_occurrences - replacements_made))

    restored = restore_code_segments("".join(annotated_parts), code_replacements)
    return restored, selection_replacements


def restore_selection_highlight_placeholders(text, selection_replacements):
    restored = str(text or "")
    for placeholder, html_value in (selection_replacements or {}).items():
        restored = restored.replace(placeholder, html_value)
    return restored


def annotate_text_with_glossary(text, glossary_entries, occurrence_counts=None, max_occurrences_per_term=2):
    if not glossary_entries:
        return text

    protected_text, code_replacements = protect_code_segments(text)
    occurrence_counts = occurrence_counts if occurrence_counts is not None else {}

    # Markdown headings are left unannotated. A glossary span carries a
    # block-level hover card, and inside a heading that forces the heading to
    # wrap onto two lines. Only the first couple of occurrences of a term are
    # highlighted, so whichever heading happens to hold the first one would
    # break; protecting headings keeps the highlighting in the body text where
    # it belongs.
    heading_replacements = {}

    def _protect_heading(match):
        placeholder = f"@@GLOSSARYHEADING{len(heading_replacements)}@@"
        heading_replacements[placeholder] = match.group(0)
        return placeholder

    protected_text = re.sub(
        r"^[ \t]{0,3}#{1,6}[ \t].*$",
        _protect_heading,
        protected_text,
        flags=re.MULTILINE,
    )

    html_parts = re.split(r"(<[^>]+>)", protected_text)
    annotated_parts = []
    glossary_replacements = {}

    for html_part in html_parts:
        if html_part.startswith("<") and html_part.endswith(">"):
            annotated_parts.append(html_part)
            continue

        annotated_segment = html_part
        for canonical_term, meta in glossary_entries.items():
            aliases = meta.get("_aliases", [canonical_term])
            for alias in aliases:
                pattern = re.compile(rf"(?<!\w)({re.escape(alias)})(?!\w)", flags=re.IGNORECASE)

                def _replace(match, canonical_term=canonical_term, meta=meta):
                    seen = occurrence_counts.get(canonical_term, 0)
                    if seen >= max_occurrences_per_term:
                        return match.group(1)
                    occurrence_counts[canonical_term] = seen + 1
                    placeholder = f"@@GLOSSARY_TERM_{len(glossary_replacements)}@@"
                    glossary_replacements[placeholder] = make_glossary_span(match.group(1), canonical_term, meta)
                    return placeholder

                annotated_segment = pattern.sub(_replace, annotated_segment)

        annotated_parts.append(annotated_segment)

    restored = restore_code_segments("".join(annotated_parts), code_replacements)
    for placeholder, heading_line in heading_replacements.items():
        restored = restored.replace(placeholder, heading_line)
    for placeholder, html_value in glossary_replacements.items():
        restored = restored.replace(placeholder, html_value)
    return restored


def render_glossary_bank(glossary_entries, context_label="this lesson"):
    if not glossary_entries:
        st.info("No glossary terms were detected for this section yet.")
        return

    cards = ['<div class="glossary-bank">']
    for canonical_term, meta in glossary_entries.items():
        plain = html_escape(meta.get("plain", "No short definition available."))
        context = html_escape(meta.get("context", plain))
        read_more = html_escape(meta.get("read_more", ""))
        scope_label = html_escape(meta.get("_scope_label", ""))
        aliases = [alias for alias in meta.get("_aliases", []) if alias.lower() != canonical_term.lower()]
        alias_text = ", ".join(aliases[:4])

        cards.append(
            f"""
            <details class="glossary-card">
                <summary>
                    <span class="glossary-card-term">{html_escape(canonical_term)}</span>
                    <span class="glossary-card-subtitle">{context}</span>
                </summary>
                <div class="glossary-card-body">
                    <p><strong>Plain meaning:</strong> {plain}</p>
                    <p><strong>In context:</strong> {context}</p>
                    {f"<p><strong>Read more:</strong> {read_more}</p>" if read_more else ""}
                    {f"<p><strong>Saved in:</strong> {scope_label}</p>" if scope_label else ""}
                    {f"<p><strong>Also appears as:</strong> {html_escape(alias_text)}</p>" if alias_text else ""}
                </div>
            </details>
            """
        )
    cards.append("</div>")
    st.markdown(
        f"Use this word bank to unpack difficult terms from {context_label}. Hover highlighted words in the lesson text for quick meanings, or open any term below to read more.",
        unsafe_allow_html=False,
    )
    st.markdown("".join(cards), unsafe_allow_html=True)


def render_glossary_selection_capture(component_key):
    return _selection_capture_component(key=component_key, default="", height=92)


def get_course_name_from_code(course_code):
    for course in courses_data:
        if course.get("code") == course_code:
            return course.get("name", course_code)
    return course_code


def build_glossary_flashcard_back(meta):
    parts = [str(meta.get("plain", "")).strip()]
    context = str(meta.get("context", "")).strip()
    read_more = str(meta.get("read_more", "")).strip()
    if context and context not in parts:
        parts.append(f"In context: {context}")
    if read_more:
        parts.append(f"Read more: {read_more}")
    return "\n\n".join(part for part in parts if part)


def render_lesson_glossary_manager(course_code, course_name, lesson, lesson_glossary_entries, global_capture_payload=None):
    lesson_number = lesson.get("lesson_number")
    lesson_title = lesson.get("title", "")
    lesson_text = " ".join(
        [
            str(lesson.get("title", "")),
            str(lesson.get("content", "")),
            " ".join(str(point) for point in lesson.get("key_points", [])),
        ]
    )

    term_input_key = f"custom_glossary_term_{course_code}_{lesson_number}"
    plain_input_key = f"custom_glossary_plain_{course_code}_{lesson_number}"
    context_input_key = f"custom_glossary_context_{course_code}_{lesson_number}"
    read_more_input_key = f"custom_glossary_read_more_{course_code}_{lesson_number}"
    aliases_input_key = f"custom_glossary_aliases_{course_code}_{lesson_number}"
    capture_state_key = f"custom_glossary_last_capture_{course_code}_{lesson_number}"
    scope_key = f"custom_glossary_scope_{course_code}_{lesson_number}"
    flashcard_key = f"custom_glossary_flashcard_{course_code}_{lesson_number}"
    manager_open_key = f"custom_glossary_manager_open_{course_code}_{lesson_number}"
    explain_text_key = f"lesson_selected_explain_text_{course_code}_{lesson_number}"
    explain_output_key = f"lesson_selected_explain_output_{course_code}_{lesson_number}"
    explain_open_key = f"lesson_selected_explain_open_{course_code}_{lesson_number}"
    explain_mode_key = f"lesson_selected_explain_mode_{course_code}_{lesson_number}"

    st.session_state.setdefault(scope_key, "Lesson")
    st.session_state.setdefault(flashcard_key, False)
    st.session_state.setdefault(manager_open_key, False)
    st.session_state.setdefault(explain_open_key, False)
    st.session_state.setdefault(explain_mode_key, "explain")

    def prefill_glossary_suggestion(term):
        suggestion = generate_glossary_suggestion(
            term,
            lesson_text,
            lesson_title=lesson_title,
            course_name=course_name,
        )
        st.session_state[plain_input_key] = suggestion.get("plain", "")
        st.session_state[context_input_key] = suggestion.get("context", "")
        st.session_state[read_more_input_key] = suggestion.get("read_more", "")

    def prefill_selection_explanation(selected_text):
        st.session_state[explain_text_key] = selected_text
        st.session_state[explain_output_key] = generate_selection_explanation(
            selected_text,
            lesson_text,
            lesson_title=lesson_title,
            course_name=course_name,
        )
        st.session_state[explain_mode_key] = "explain"
        st.session_state[explain_open_key] = True

    def prefill_selection_exam_answer(selected_text):
        st.session_state[explain_text_key] = selected_text
        st.session_state[explain_output_key] = generate_selection_exam_answer(
            selected_text,
            lesson_text,
            lesson_title=lesson_title,
            course_name=course_name,
        )
        st.session_state[explain_mode_key] = "answer"
        st.session_state[explain_open_key] = True

    with st.expander("➕ Capture, explain, and save difficult words", expanded=bool(st.session_state.get(manager_open_key))):
        st.markdown(
            f'<div class="study-buddy-lesson-glossary-anchor" data-study-buddy-course="{html_escape(str(course_code))}" data-study-buddy-lesson="{html_escape(str(lesson_number))}" data-study-buddy-lesson-title="{html_escape(str(lesson_title))}"></div>',
            unsafe_allow_html=True,
        )
        st.markdown(
            """
            <div class="lesson-glossary-shell">
              <div class="lesson-glossary-title">Build this lesson word bank as you read</div>
              <div class="lesson-glossary-copy">Highlight a word, sentence, or whole question in the lesson and use the quick actions to save it, explain it, or turn it into an exam-style answer.</div>
            </div>
            """,
            unsafe_allow_html=True,
        )
        st.caption("Highlight a word, phrase, or whole question anywhere inside this lesson and use the quick actions that appear. From there you can save it to your glossary, ask for an AI explanation, or get an exam-style answer.")

        captured_payload = global_capture_payload
        captured_term = ""
        captured_action = "lesson"
        captured_course_code = ""
        captured_lesson_number = ""
        if isinstance(captured_payload, dict):
            captured_term = str(captured_payload.get("term", "")).strip()
            captured_action = str(captured_payload.get("action", "lesson")).strip().lower() or "lesson"
            captured_course_code = str(captured_payload.get("course_code", "")).strip()
            captured_lesson_number = str(captured_payload.get("lesson_number", "")).strip()
            capture_signature = json.dumps(captured_payload, sort_keys=True)
        else:
            captured_term = str(captured_payload or "").strip()
            capture_signature = captured_term

        capture_matches_lesson = (
            captured_term
            and (not captured_course_code or captured_course_code == str(course_code))
            and (not captured_lesson_number or captured_lesson_number == str(lesson_number))
        )

        if capture_matches_lesson and capture_signature != st.session_state.get(capture_state_key):
            st.session_state[term_input_key] = captured_term
            if captured_action == "course":
                st.session_state[scope_key] = "Course"
            elif captured_action == "global":
                st.session_state[scope_key] = "Global"
            else:
                st.session_state[scope_key] = "Lesson"
            if captured_action == "suggest":
                prefill_selection_explanation(captured_term)
            elif captured_action == "answer":
                prefill_selection_exam_answer(captured_term)
            st.session_state[capture_state_key] = capture_signature
            st.session_state[manager_open_key] = True
            st.rerun()

        if st.session_state.get(explain_open_key) and st.session_state.get(explain_output_key):
            selected_label = st.session_state.get(explain_text_key, "").strip()
            selected_label = selected_label if len(selected_label) <= 140 else f"{selected_label[:137]}..."
            explain_mode = st.session_state.get(explain_mode_key, "explain")
            title_text = "AI explanation for the selected text" if explain_mode == "explain" else "AI exam-style answer for the selected text"
            copy_text = (
                "Use this when you highlight a whole question, sentence, or concept and want a clearer, exam-friendly explanation."
                if explain_mode == "explain"
                else "Use this when you want the selected text turned into a short, human exam-style answer you can reuse later."
            )
            st.markdown(
                f"""
                <div class="lesson-glossary-toolbar">
                  <div class="lesson-glossary-toolbar-title">{html_escape(title_text)}</div>
                  <div class="lesson-glossary-toolbar-copy">{html_escape(copy_text)}</div>
                </div>
                """,
                unsafe_allow_html=True,
            )
            if selected_label:
                st.caption(f"Selected text: {selected_label}")
                st.caption("The selected text is highlighted in the lesson content below while this explanation is open.")
            current_output = st.session_state.get(explain_output_key, "")
            st.markdown(current_output)
            explain_col1, explain_col2, explain_col3, explain_col4 = st.columns([1.1, 1.2, 1.3, 0.9])
            with explain_col1:
                if st.button("Copy answer", key=f"copy_selected_explain_{course_code}_{lesson_number}", use_container_width=True):
                    trigger_clipboard_copy(current_output, key_suffix=f"{course_code}_{lesson_number}_{explain_mode}")
                    st.success("Copied to clipboard.")
            with explain_col2:
                if st.button("Send to Study Notes", key=f"save_selected_explain_notes_{course_code}_{lesson_number}", use_container_width=True):
                    prompt_text = st.session_state.get(explain_text_key, "").strip() or f"Selected text from Lesson {lesson_number}"
                    note_title_prefix = "AI Explanation" if explain_mode == "explain" else "AI Exam Answer"
                    note_title = f"{note_title_prefix}: {prompt_text[:70]}"
                    ok, msg = save_ai_text_to_study_notes(
                        course_code,
                        note_title,
                        current_output,
                        tags=["ai-generated", "selected-text", explain_mode],
                        category="exam" if explain_mode == "answer" else "summary",
                        importance="important",
                    )
                    (st.success if ok else st.info)(msg)
            with explain_col3:
                if st.button("Save as flashcard", key=f"save_selected_explain_flashcard_{course_code}_{lesson_number}", use_container_width=True):
                    explanation_text = current_output.strip()
                    prompt_text = st.session_state.get(explain_text_key, "").strip() or f"Selected text from Lesson {lesson_number}"
                    ok, msg = create_flashcard(
                        prompt_text,
                        explanation_text,
                        course_code=course_code,
                        tags=["selected-text", "ai-explanation", "lesson-support"],
                    )
                    (st.success if ok else st.info)(msg)
            with explain_col4:
                if st.button("Clear explanation", key=f"clear_selected_explain_{course_code}_{lesson_number}", use_container_width=True):
                    st.session_state[explain_text_key] = ""
                    st.session_state[explain_output_key] = ""
                    st.session_state[explain_open_key] = False
                    st.session_state[explain_mode_key] = "explain"
                    st.rerun()
            with st.expander("Copy-ready text", expanded=False):
                st.text_area(
                    "Copy-ready answer",
                    value=current_output,
                    height=220,
                    key=f"copy_ready_selected_explain_{course_code}_{lesson_number}",
                )

        candidate_terms = detect_difficult_word_candidates(lesson_text, lesson_glossary_entries)
        if candidate_terms:
            st.markdown(
                """
                <div class="lesson-glossary-toolbar">
                  <div class="lesson-glossary-toolbar-title">Possible subject terms detected automatically</div>
                  <div class="lesson-glossary-toolbar-copy">These suggestions now prioritise technical vocabulary, formulas, acronyms, and subject phrases from the lesson instead of only long or uncommon words.</div>
                </div>
                """,
                unsafe_allow_html=True,
            )
            candidate_cols = st.columns(2)
            for idx, candidate in enumerate(candidate_terms):
                with candidate_cols[idx % 2]:
                    st.markdown(
                        f"""
                        <div class="lesson-glossary-candidate">
                          <div class="lesson-glossary-candidate-term">{html_escape(candidate['term'])}</div>
                          <div class="lesson-glossary-candidate-meta">{html_escape(candidate.get('reason', 'Potentially difficult term from the lesson'))}</div>
                          <div class="lesson-glossary-candidate-meta">Appears {candidate['count']} time(s) in this lesson</div>
                        </div>
                        """,
                        unsafe_allow_html=True,
                    )
                    if st.button(
                        f"Add {candidate['term']} ({candidate['count']}x)",
                        key=f"candidate_term_{course_code}_{lesson_number}_{idx}",
                        use_container_width=True,
                    ):
                        st.session_state[term_input_key] = candidate["term"]
                        st.session_state[manager_open_key] = True
                        st.rerun()
                    st.caption(candidate["snippet"])

        st.markdown(
            """
            <div class="lesson-glossary-toolbar">
              <div class="lesson-glossary-toolbar-title">Capture and improve the explanation</div>
              <div class="lesson-glossary-toolbar-copy">Use AI suggestions as a draft, then rewrite them into the clearest wording for your own exam memory.</div>
            </div>
            """,
            unsafe_allow_html=True,
        )
        control_col1, control_col2, control_col3 = st.columns([1.1, 1.1, 1.8])
        with control_col1:
            if st.button("Explain selected text", key=f"suggest_glossary_{course_code}_{lesson_number}", use_container_width=True):
                current_term = st.session_state.get(term_input_key, "").strip()
                if current_term:
                    prefill_selection_explanation(current_term)
                    st.session_state[manager_open_key] = True
                    st.rerun()
                else:
                    st.warning("Choose or capture a term first.")
        with control_col2:
            if st.button("Answer like exam", key=f"answer_selected_text_{course_code}_{lesson_number}", use_container_width=True):
                current_term = st.session_state.get(term_input_key, "").strip()
                if current_term:
                    prefill_selection_exam_answer(current_term)
                    st.session_state[manager_open_key] = True
                    st.rerun()
                else:
                    st.warning("Choose or capture a term first.")
        with control_col3:
            if st.button("Clear form", key=f"clear_glossary_form_{course_code}_{lesson_number}", use_container_width=True):
                for key in [term_input_key, plain_input_key, context_input_key, read_more_input_key, aliases_input_key]:
                    st.session_state[key] = ""
                st.session_state[manager_open_key] = False
                st.rerun()

        if client is None:
            st.caption("AI is not configured, so explanation and exam-answer drafts fall back to lesson-context hints.")
        else:
            provider_label = AI_PROVIDER_LABEL or "configured AI provider"
            model_label = AI_CHAT_MODEL or "configured model"
            provider_caption = f"AI can now either explain the selected text or turn it into a short exam-style answer. Current provider: {provider_label} ({model_label})."
            if ai_provider_is_local():
                provider_caption += f" Mode: {get_local_ai_response_mode()}."
            st.caption(provider_caption)

        if client is not None and ai_provider_is_local():
            local_mode = st.selectbox(
                "Local AI response mode",
                options=list(AI_LOCAL_RESPONSE_MODES.keys()),
                key="local_ai_response_mode",
                help="Choose whether the local model should optimise for speed or give slightly fuller answers.",
            )
            st.caption(AI_LOCAL_RESPONSE_MODES[local_mode]["helper_text"])

        with st.form(f"custom_glossary_form_{course_code}_{lesson_number}"):
            custom_term = st.text_input("Word or phrase", key=term_input_key, placeholder="Example: heteroscedasticity")
            form_col1, form_col2 = st.columns([1, 1])
            with form_col1:
                custom_scope = st.selectbox("Save in", options=["Lesson", "Course", "Global"], key=scope_key)
            with form_col2:
                add_flashcard = st.checkbox("Also create flashcard", key=flashcard_key)
            custom_plain = st.text_input("Quick meaning for hover", key=plain_input_key, placeholder="Short explanation shown on hover")
            custom_context = st.text_input("Meaning in this lesson", key=context_input_key, placeholder="What the word means in the context of this lesson")
            custom_read_more = st.text_area("Read more", key=read_more_input_key, placeholder="Longer note, example, or reminder for future revision")
            custom_aliases = st.text_input("Optional aliases", key=aliases_input_key, placeholder="Comma-separated variants, e.g. KPI, key performance indicator")
            submitted_custom_term = st.form_submit_button("Save word")

        if submitted_custom_term:
            ok, message = upsert_custom_glossary_entry(
                custom_scope,
                course_code,
                lesson_number,
                custom_term,
                custom_plain,
                context=custom_context,
                read_more=custom_read_more,
                aliases_text=custom_aliases,
            )
            if ok:
                if add_flashcard:
                    create_flashcard(
                        custom_term,
                        build_glossary_flashcard_back(
                            {
                                "plain": custom_plain,
                                "context": custom_context,
                                "read_more": custom_read_more,
                            }
                        ),
                        course_code=course_code,
                        tags=["glossary", "lesson-word-bank"],
                    )
                for key in [term_input_key, plain_input_key, context_input_key, read_more_input_key, aliases_input_key]:
                    st.session_state[key] = ""
                st.session_state[flashcard_key] = False
                st.session_state[manager_open_key] = False
                st.success(message)
                st.rerun()
            else:
                st.warning(message)

        st.markdown(
            """
            <div class="lesson-glossary-toolbar">
              <div class="lesson-glossary-toolbar-title">Saved custom terms active in this lesson</div>
              <div class="lesson-glossary-toolbar-copy">These are the terms currently enriching the text for this lesson, including inherited global and course-level entries.</div>
            </div>
            """,
            unsafe_allow_html=True,
        )
        scope_sections = [
            ("Global", get_custom_global_glossary_entries()),
            ("Course", get_custom_course_scope_glossary_entries(course_code)),
            ("Lesson", get_custom_lesson_scope_glossary_entries(course_code, lesson_number)),
        ]
        shown_any = False
        for scope_label, entries in scope_sections:
            if not entries:
                continue
            shown_any = True
            st.markdown(f'<div class="lesson-glossary-scope-heading">{html_escape(scope_label)} scope</div>', unsafe_allow_html=True)
            for custom_term, custom_meta in entries.items():
                col_term, col_scope, col_flash, col_delete = st.columns([4.3, 1.3, 1.2, 0.7])
                with col_term:
                    st.markdown(
                        f"""
                        <div class="lesson-glossary-saved-card">
                          <div class="lesson-glossary-saved-term">{html_escape(custom_term)}</div>
                          <div class="lesson-glossary-saved-plain">{html_escape(custom_meta.get('plain', 'Custom glossary term.'))}</div>
                        </div>
                        """,
                        unsafe_allow_html=True,
                    )
                with col_scope:
                    st.caption(custom_meta.get("_scope_label", scope_label))
                with col_flash:
                    if st.button("🎴", key=f"flash_glossary_{scope_label}_{course_code}_{lesson_number}_{custom_term}", help=f"Create flashcard for {custom_term}"):
                        ok, msg = create_flashcard(
                            custom_term,
                            build_glossary_flashcard_back(custom_meta),
                            course_code=course_code,
                            tags=["glossary", "lesson-word-bank"],
                        )
                        (st.success if ok else st.info)(msg)
                with col_delete:
                    if st.button("🗑️", key=f"delete_glossary_{scope_label}_{course_code}_{lesson_number}_{custom_term}", help=f"Remove {custom_term}"):
                        delete_custom_glossary_entry(scope_label, course_code, lesson_number, custom_term)
                        st.rerun()
        if not shown_any:
            st.info("No custom terms saved for this lesson yet.")


def render_my_glossary_page():
    st.markdown(
        """
        <style>
        .my-glossary-hero {
            background:
                radial-gradient(circle at top left, rgba(251, 191, 36, 0.24), transparent 32%),
                linear-gradient(135deg, #fffdf5 0%, #f8fbff 55%, #eef6ff 100%);
            border: 1px solid #e8eef8;
            border-radius: 18px;
            padding: 18px 20px;
            margin-bottom: 16px;
        }
        .my-glossary-hero h2 {
            margin: 0 0 6px 0;
            color: #0f172a;
            font-size: 1.45rem;
        }
        .my-glossary-hero p {
            margin: 0;
            color: #475569;
            line-height: 1.55;
        }
        .my-glossary-toolbar {
            background: #f8fafc;
            border: 1px solid #e2e8f0;
            border-radius: 16px;
            padding: 14px;
            margin-bottom: 12px;
        }
        .my-glossary-chip-row {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            margin: 10px 0 0 0;
        }
        .my-glossary-chip {
            display: inline-flex;
            align-items: center;
            border-radius: 999px;
            padding: 6px 10px;
            font-size: 0.82rem;
            font-weight: 600;
            background: #eef4ff;
            color: #1e3a8a;
            border: 1px solid #c7d2fe;
        }
        .my-glossary-section-title {
            margin: 8px 0 6px 0;
            font-size: 1.02rem;
            font-weight: 700;
            color: #0f172a;
        }
        .my-glossary-term-card {
            border: 1px solid #e5e7eb;
            background: white;
            border-radius: 14px;
            padding: 12px 14px;
            margin-bottom: 10px;
            box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
        }
        .my-glossary-term-card h4 {
            margin: 0 0 4px 0;
            color: #111827;
            font-size: 1rem;
        }
        .my-glossary-term-card p {
            margin: 0;
            color: #475569;
            line-height: 1.45;
        }
        .my-glossary-quiz-box {
            border: 1px solid #dbeafe;
            background: linear-gradient(180deg, #f8fbff 0%, #ffffff 100%);
            border-radius: 18px;
            padding: 16px 18px;
            margin-top: 10px;
        }
        .my-glossary-subtle {
            color: #64748b;
            font-size: 0.92rem;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )

    st.title("🧠 My Glossary")
    st.markdown(
        """
        <div class="my-glossary-hero">
          <h2>Your personal word bank</h2>
          <p>Keep difficult words in one place, turn them into flashcards, and rehearse them until the language in the lessons feels natural.</p>
        </div>
        """,
        unsafe_allow_html=True,
    )

    custom_entries = iter_custom_glossary_entries()
    total_terms = len(custom_entries)
    global_count = sum(1 for entry in custom_entries if entry["scope"] == "Global")
    course_count = sum(1 for entry in custom_entries if entry["scope"] == "Course")
    lesson_count = sum(1 for entry in custom_entries if entry["scope"] == "Lesson")

    stat_cols = st.columns(4)
    stat_cols[0].metric("Saved terms", total_terms)
    stat_cols[1].metric("Global", global_count)
    stat_cols[2].metric("Course", course_count)
    stat_cols[3].metric("Lesson", lesson_count)

    tab1, tab2, tab3 = st.tabs(["📚 Saved Terms", "🗂 Course Word Banks", "🎯 Glossary Quiz"])

    with tab1:
        if not custom_entries:
            st.info("You have not saved any custom glossary terms yet. Add terms from Learn & Practice to build your own bank.")
        else:
            st.markdown(
                """
                <div class="my-glossary-toolbar">
                  <div class="my-glossary-section-title">Filter and export</div>
                  <div class="my-glossary-subtle">Narrow the list, export the visible subset, or turn the current selection into flashcards.</div>
                </div>
                """,
                unsafe_allow_html=True,
            )
            filter_col1, filter_col2, filter_col3 = st.columns([2, 2, 1.3])
            with filter_col1:
                search_term = st.text_input("Search terms", placeholder="Search a word or definition")
            with filter_col2:
                course_options = ["All Courses"] + sorted({entry["course_code"] for entry in custom_entries if entry["course_code"]})
                selected_course = st.selectbox("Course filter", course_options)
            with filter_col3:
                selected_scope = st.selectbox("Scope", ["All", "Global", "Course", "Lesson"])

            visible_entries = []
            search_key = search_term.strip().lower()
            for entry in custom_entries:
                haystack = " ".join(
                    [
                        entry["term"],
                        entry["meta"].get("plain", ""),
                        entry["meta"].get("context", ""),
                        entry["meta"].get("read_more", ""),
                    ]
                ).lower()
                if search_key and search_key not in haystack:
                    continue
                if selected_course != "All Courses" and entry["course_code"] != selected_course:
                    continue
                if selected_scope != "All" and entry["scope"] != selected_scope:
                    continue
                visible_entries.append(entry)

            chip_parts = [f'<span class="my-glossary-chip">Visible terms: {len(visible_entries)}</span>']
            if search_key:
                chip_parts.append(f'<span class="my-glossary-chip">Search: {html_escape(search_term.strip())}</span>')
            if selected_course != "All Courses":
                chip_parts.append(f'<span class="my-glossary-chip">Course: {html_escape(selected_course)}</span>')
            if selected_scope != "All":
                chip_parts.append(f'<span class="my-glossary-chip">Scope: {html_escape(selected_scope)}</span>')
            st.markdown(f'<div class="my-glossary-chip-row">{"".join(chip_parts)}</div>', unsafe_allow_html=True)

            export_payload = [
                {
                    "term": entry["term"],
                    "scope": entry["scope"],
                    "course_code": entry["course_code"],
                    "lesson_number": entry["lesson_number"],
                    "plain": entry["meta"].get("plain", ""),
                    "context": entry["meta"].get("context", ""),
                    "read_more": entry["meta"].get("read_more", ""),
                }
                for entry in visible_entries
            ]
            st.download_button(
                "Download visible glossary as JSON",
                data=json.dumps(export_payload, ensure_ascii=False, indent=2),
                file_name="my_glossary.json",
                mime="application/json",
                use_container_width=False,
            )

            if st.button("Create flashcards from visible terms", key="bulk_glossary_flashcards"):
                added = 0
                for entry in visible_entries:
                    ok, _ = create_flashcard(
                        entry["term"],
                        build_glossary_flashcard_back(entry["meta"]),
                        course_code=entry["course_code"],
                        tags=["glossary", "bulk-import"],
                    )
                    if ok:
                        added += 1
                st.success(f"Created {added} new flashcards from the visible glossary terms.")

            st.markdown('<div class="my-glossary-section-title">Saved entries</div>', unsafe_allow_html=True)
            if not visible_entries:
                st.info("No saved terms match the current filters.")
            for entry in visible_entries:
                meta = entry["meta"]
                st.markdown(
                    f"""
                    <div class="my-glossary-term-card">
                      <h4>{html_escape(entry['term'])}</h4>
                      <p>{html_escape(meta.get('plain', ''))}</p>
                    </div>
                    """,
                    unsafe_allow_html=True,
                )
                with st.expander(f"{entry['term']} • {meta.get('_scope_label', entry['scope'])}", expanded=False):
                    st.markdown(f"**Plain meaning:** {meta.get('plain', '')}")
                    st.markdown(f"**In context:** {meta.get('context', '')}")
                    if meta.get("read_more"):
                        st.markdown(f"**Read more:** {meta.get('read_more')}")
                    action_col1, action_col2 = st.columns([1, 1])
                    with action_col1:
                        if st.button("Create flashcard", key=f"my_glossary_flash_{entry['scope']}_{entry['course_code']}_{entry['lesson_number']}_{entry['term']}"):
                            ok, msg = create_flashcard(
                                entry["term"],
                                build_glossary_flashcard_back(meta),
                                course_code=entry["course_code"],
                                tags=["glossary", "my-glossary"],
                            )
                            (st.success if ok else st.info)(msg)
                    with action_col2:
                        if st.button("Delete term", key=f"my_glossary_delete_{entry['scope']}_{entry['course_code']}_{entry['lesson_number']}_{entry['term']}"):
                            delete_custom_glossary_entry(entry["scope"], entry["course_code"], entry["lesson_number"], entry["term"])
                            st.rerun()

    with tab2:
        course_labels = [f"{course['code']} - {course['name']}" for course in courses_data if course.get("code") in course_lessons]
        if not course_labels:
            st.info("No lesson-based word banks are available yet.")
        else:
            selected_course_label = st.selectbox("Course word bank", course_labels, key="my_glossary_course_bank")
            selected_course_code = selected_course_label.split(" - ", 1)[0]
            system_bank = merge_glossary_entry_sets(
                get_course_glossary_entries(course_lessons.get(selected_course_code, [])),
                get_course_custom_glossary_entries(selected_course_code),
            )
            st.markdown(
                """
                <div class="my-glossary-toolbar">
                  <div class="my-glossary-section-title">Browse course-level terms</div>
                  <div class="my-glossary-subtle">Use this view when you want to pull useful built-in terms into your own glossary or turn them into flashcards.</div>
                </div>
                """,
                unsafe_allow_html=True,
            )
            render_glossary_bank(system_bank, context_label=f"{selected_course_label}")
            if system_bank:
                selected_system_term = st.selectbox(
                    "Choose a term from this course word bank",
                    options=list(system_bank.keys()),
                    key=f"system_glossary_term_{selected_course_code}",
                )
                selected_meta = system_bank[selected_system_term]
                action_col1, action_col2 = st.columns(2)
                with action_col1:
                    if st.button("Save selected term to my glossary", key=f"copy_system_term_{selected_course_code}"):
                        ok, message = upsert_custom_glossary_entry(
                            "Course",
                            selected_course_code,
                            "",
                            selected_system_term,
                            selected_meta.get("plain", ""),
                            context=selected_meta.get("context", ""),
                            read_more=selected_meta.get("read_more", ""),
                            aliases_text=", ".join(
                                alias for alias in selected_meta.get("_aliases", []) if alias.lower() != selected_system_term.lower()
                            ),
                        )
                        (st.success if ok else st.info)(message)
                with action_col2:
                    if st.button("Create flashcard for selected term", key=f"flash_system_term_{selected_course_code}"):
                        ok, message = create_flashcard(
                            selected_system_term,
                            build_glossary_flashcard_back(selected_meta),
                            course_code=selected_course_code,
                            tags=["glossary", "course-word-bank"],
                        )
                        (st.success if ok else st.info)(message)

    with tab3:
        quiz_pool = custom_entries[:]
        if not quiz_pool:
            st.info("Save some custom terms first, then use this tab to quiz yourself.")
        else:
            st.markdown(
                """
                <div class="my-glossary-quiz-box">
                  <div class="my-glossary-section-title">Quick recall mode</div>
                  <div class="my-glossary-subtle">Pick a random term, try to define it in your own words first, and then reveal the saved explanation.</div>
                </div>
                """,
                unsafe_allow_html=True,
            )
            if st.button("Pick random glossary term", key="glossary_quiz_pick"):
                st.session_state.my_glossary_quiz_term = random.choice(quiz_pool)
                st.session_state.my_glossary_quiz_reveal = False
                st.session_state.my_glossary_quiz_guess = ""
                st.rerun()

            current_quiz_entry = st.session_state.get("my_glossary_quiz_term")
            if not current_quiz_entry:
                st.info("Pick a random glossary term to start.")
            else:
                meta = current_quiz_entry["meta"]
                st.markdown(f"### {current_quiz_entry['term']}")
                st.caption(f"Scope: {meta.get('_scope_label', current_quiz_entry['scope'])}")
                st.markdown(
                    f"""
                    <div class="my-glossary-term-card">
                      <h4>Recall prompt</h4>
                      <p>Try to explain <strong>{html_escape(current_quiz_entry['term'])}</strong> without looking at the saved answer first.</p>
                    </div>
                    """,
                    unsafe_allow_html=True,
                )
                answer_guess = st.text_area("What do you think this means?", key="my_glossary_quiz_guess")
                reveal = st.checkbox("Reveal answer", key="my_glossary_quiz_reveal")
                if reveal:
                    st.success(meta.get("plain", ""))
                    st.markdown(f"**In context:** {meta.get('context', '')}")
                    if meta.get("read_more"):
                        st.markdown(f"**Read more:** {meta.get('read_more')}")
                if answer_guess.strip():
                    st.caption("Use your own wording first, then reveal the stored meaning and compare.")

