        # Total study time
        total_seconds = sum(s.get('duration', 0) for s in st.session_state.study_sessions)
        total_hours = total_seconds // 3600
        total_minutes = (total_seconds % 3600) // 60
        
        st.metric("Total Study Time", f"{total_hours}h {total_minutes}m")
